import{_ as a,C as e,c as i,o as n,ag as t,G as p}from"./chunks/framework.BD8wkLub.js";const v=JSON.parse('{"title":"前端学习 TODO 列表","description":"","frontmatter":{},"headers":[],"relativePath":"demo.md","filePath":"demo.md"}'),o={name:"demo.md"};function r(c,l,d,h,u,m){const s=e("TaskList");return n(),i("div",null,[l[0]||(l[0]=t(`<h1 id="前端学习-todo-列表" tabindex="-1">前端学习 TODO 列表 <a class="header-anchor" href="#前端学习-todo-列表" aria-label="Permalink to &quot;前端学习 TODO 列表&quot;">​</a></h1><h2 id="前端基础" tabindex="-1">前端基础 <a class="header-anchor" href="#前端基础" aria-label="Permalink to &quot;前端基础&quot;">​</a></h2><ul><li><p>了解 <strong>服务器映射</strong></p><ul><li><p>ATP 服务器如何把文件夹映射成网站</p><ol><li><p>假设有一个文件夹 /var/www/html/a.html, 当你在浏览器里输入：<code>http://localhost/a.html</code>, 浏览器会发送一个http请求给<code>localhost</code></p></li><li><p>浏览器发出的请求会被服务器解析: 服务器监听某个端口（比如 8080），接收到请求后：</p><ul><li>把请求路径 <code>/index.html</code> 拼接到服务器设定的 根目录，比如：<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>根目录: /var/www/html</span></span>
<span class="line"><span>路径:   /index.html</span></span>
<span class="line"><span>真实文件: /var/www/html/index.html</span></span></code></pre></div></li></ul></li><li><p>读取文件并返回 服务器检查文件是否存在，如果存在就读取内容。 返回响应：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>HTTP/1.1 200 OK</span></span>
<span class="line"><span> Content-Type: text/html</span></span></code></pre></div></li><li><p>浏览器渲染：</p><ul><li>浏览器收到内容，解析 HTML，遇到<code>&lt;link&gt; &lt;script&gt; &lt;img&gt;</code>再发请求。</li><li>服务器同样按照路径规则找到对应文件，继续返回。</li></ul></li></ol></li><li><p><strong>Web 服务器怎么知道去哪个文件夹找文件?</strong></p><ol><li>在于 服务器配置（通常在 Web 服务器软件里，比如 Nginx/Apache/Node.js）</li></ol><ul><li>server_name 或 端口号 → 映射到 某个文件夹，如：<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>例如在NGINX：</span></span>
<span class="line"><span># 网站1 配置</span></span>
<span class="line"><span>  server {</span></span>
<span class="line"><span>      listen 80;                        # 监听 80 端口</span></span>
<span class="line"><span>      server_name site1.com;            # 或指定域名</span></span>
<span class="line"><span>      root /var/www/site1;              # 根目录 = 文件夹A</span></span>
<span class="line"><span>      index index.html;</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 网站2 配置</span></span>
<span class="line"><span>  server {</span></span>
<span class="line"><span>      listen 90;                        # 监听 90 端口</span></span>
<span class="line"><span>      server_name site2.com;</span></span>
<span class="line"><span>      root /var/www/site2;              # 根目录 = 文件夹B</span></span>
<span class="line"><span>      index index.html;</span></span>
<span class="line"><span>  }</span></span></code></pre></div></li></ul><p>这样：</p><ul><li>请求 <code>http://localhost:80/index.html</code> → 去 /var/www/site1/index.html</li><li>请求 <code>http://localhost:90/index.html</code> → 去 /var/www/site2/index.html</li></ul><ol start="2"><li>服务器是如何“知道”的? <ul><li>操作系统级别： <ul><li>TCP/IP 协议栈收到请求，发现请求端口 = 80</li><li>把这个请求交给正在监听 80 端口的进程（比如 Nginx）</li></ul></li><li>Web 服务器级别： <ul><li>Web 服务器看请求的 Host（域名）和端口号</li><li>匹配到配置文件里对应的规则（哪个 server 块）。</li></ul></li><li>文件系统映射： <ul><li>把请求路径 /xxx.html 拼接到配置里的 root 路径（例如 /var/www/site1）。</li><li>得到真实路径 /var/www/site1/xxx.html</li><li>读取文件，返回给浏览器。</li></ul></li></ul></li></ol><p><strong>总结：操作系统只负责把请求交给监听该端口的进程；而具体请求路径对应哪个文件夹（根目录），完全是由 Web 服务器配置文件决定的。</strong></p></li><li><p>Node 工具：<code>http-server</code> 映射文件夹</p></li><li><p>搞清楚 <strong>404 与 500 的区别</strong> （A 找不到 B → 404；A 自己出错 → 500）</p></li></ul></li><li><p>搞懂 <strong>index.html 的作用</strong></p><ul><li>index 是前端项目的默认入口</li><li>目录暴露的安全措施要了解一下</li><li>为什么 index 默认只能是纯文本显示？（表格、样式需要额外引入）</li></ul></li><li><p>熟悉 <strong>文件路径规则</strong></p><ul><li>路径找文件：文件夹下默认找 <code>index.html</code></li><li><code>./assets/a.css</code> vs <code>/assets/a.css</code> 的区别</li><li>本地文件访问（双击 <code>D:/xxx.html</code>） vs 服务器访问（<code>http://localhost:port</code>）</li></ul></li></ul><hr><h2 id="html-css-js" tabindex="-1">HTML / CSS / JS <a class="header-anchor" href="#html-css-js" aria-label="Permalink to &quot;HTML / CSS / JS&quot;">​</a></h2><ul><li><p>写一个最基础的 <strong>HTML 页面</strong></p><ul><li>外部引入 JS &amp; CSS 文件</li><li>在 HTML 里通过 <code>&lt;script&gt;</code> &amp; <code>&lt;link&gt;</code> 加载</li></ul></li><li><p>掌握加载顺序</p><ul><li>CSS 会立即应用到 DOM</li><li>JS 需要等 DOM 加载完成再运行（可用 <code>defer</code> 或 <code>DOMContentLoaded</code>）</li></ul></li><li><p>在 MDN 上查一些关键词（例如 DOM、CSSOM、加载顺序）</p></li></ul><hr><h2 id="typescript-vue" tabindex="-1">TypeScript &amp; Vue <a class="header-anchor" href="#typescript-vue" aria-label="Permalink to &quot;TypeScript &amp; Vue&quot;">​</a></h2><ul><li><p>在项目里引入 <strong>TypeScript</strong></p><ul><li>先编译 TS → JS，再在 HTML 里使用</li><li>理解为什么浏览器不能直接跑 <code>.ts</code></li></ul></li><li><p>学习 <strong>Vue 基础项目搭建</strong></p><ul><li>创建 Vue 项目（包含 TS、JSX、Vue Router、Pinia、ESLint、Prettier）</li><li>明白这些工具的作用</li></ul></li></ul><hr><h2 id="文档与静态站点" tabindex="-1">文档与静态站点 <a class="header-anchor" href="#文档与静态站点" aria-label="Permalink to &quot;文档与静态站点&quot;">​</a></h2><blockquote><p>Markdown 文件（<code>.md</code>）本身就是天然的静态资源，可以直接丢到文件夹或服务器作为文档。</p></blockquote><ul><li><p>学习 <strong>VitePress</strong></p><ul><li>在项目里初始化 VitePress</li><li>跑起来一个本地文档站点</li><li>尝试修改样式，看看能否打包离线使用</li><li>最后部署到服务器</li></ul></li><li><p>了解 <strong>MDBook</strong></p><ul><li>学习如何生成“电子书”风格的文档</li></ul></li></ul><hr><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2>`,15)),p(s,{items:["了解服务器映射 (http-server)","写基础 HTML + CSS + JS 页面","尝试 TS 编译","跑起 VitePress","学习 Vue 生态 (Router, Pinia, ESLint, Prettier)"]})])}const x=a(o,[["render",r]]);export{v as __pageData,x as default};
